/**
 * QuestionComposer — Agent 提问接管 Composer。
 *
 * 借鉴 deepseek-harness 的 QuestionComposer：
 * - Agent 向用户提问时接管输入区域
 * - 支持选项选择（单选/多选）+ 自定义输入
 * - 用户回答后恢复常规输入
 */
import { useState, useRef, useEffect } from 'react'
import { cn } from '@/lib/utils'
import { Send, HelpCircle } from 'lucide-react'

export interface AgentQuestion {
  id: string
  question: string
  options?: Array<{
    label: string
    description?: string
    value: string
  }>
  multiSelect?: boolean
  allowCustomInput?: boolean
}

interface Props {
  question: AgentQuestion
  onAnswer: (answer: string | string[]) => void
  onCancel?: () => void
  className?: string
}

export function QuestionComposer({ question, onAnswer, onCancel, className }: Props) {
  const [selected, setSelected] = useState<Set<string>>(new Set())
  const [customInput, setCustomInput] = useState('')
  const inputRef = useRef<HTMLInputElement>(null)

  useEffect(() => {
    inputRef.current?.focus()
  }, [question.id])

  const toggleOption = (value: string) => {
    setSelected((prev) => {
      const next = new Set(prev)
      if (question.multiSelect) {
        if (next.has(value)) next.delete(value)
        else next.add(value)
      } else {
        next.clear()
        next.add(value)
      }
      return next
    })
  }

  const handleSubmit = () => {
    if (customInput.trim()) {
      onAnswer(customInput.trim())
    } else if (selected.size > 0) {
      const values = Array.from(selected)
      onAnswer(question.multiSelect ? values : values[0])
    }
  }

  const canSubmit = selected.size > 0 || customInput.trim().length > 0

  return (
    <div className={cn('rounded-xl border bg-card p-4 space-y-3', className)}>
      {/* 问题标题 */}
      <div className="flex items-start gap-2">
        <HelpCircle className="h-4 w-4 shrink-0 text-primary mt-0.5" />
        <p className="text-sm font-medium">{question.question}</p>
      </div>

      {/* 选项列表 */}
      {question.options && question.options.length > 0 && (
        <div className="space-y-1.5">
          {question.options.map((opt) => (
            <button
              key={opt.value}
              onClick={() => toggleOption(opt.value)}
              className={cn(
                'flex w-full items-start gap-2 rounded-lg border px-3 py-2 text-left text-sm transition-colors',
                selected.has(opt.value)
                  ? 'border-primary bg-primary/5 text-primary'
                  : 'hover:bg-accent hover:border-accent-foreground/20',
              )}
            >
              {/* 选择指示器 */}
              <div className={cn(
                'mt-0.5 h-4 w-4 shrink-0 rounded border transition-colors',
                question.multiSelect ? 'rounded' : 'rounded-full',
                selected.has(opt.value)
                  ? 'border-primary bg-primary'
                  : 'border-muted-foreground/30',
              )} />
              <div className="flex-1 min-w-0">
                <div className="font-medium">{opt.label}</div>
                {opt.description && (
                  <div className="text-xs text-muted-foreground mt-0.5">{opt.description}</div>
                )}
              </div>
            </button>
          ))}
        </div>
      )}

      {/* 自定义输入 */}
      {(question.allowCustomInput !== false) && (
        <div className="flex items-center gap-2">
          <input
            ref={inputRef}
            value={customInput}
            onChange={(e) => setCustomInput(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === 'Enter' && canSubmit) {
                e.preventDefault()
                handleSubmit()
              }
            }}
            placeholder="或输入自定义回答..."
            className="flex-1 rounded-lg border bg-background px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-ring placeholder:text-muted-foreground"
          />
        </div>
      )}

      {/* 操作按钮 */}
      <div className="flex items-center justify-end gap-2">
        {onCancel && (
          <button
            onClick={onCancel}
            className="rounded-lg px-3 py-1.5 text-sm text-muted-foreground hover:bg-accent"
          >
            取消
          </button>
        )}
        <button
          onClick={handleSubmit}
          disabled={!canSubmit}
          className={cn(
            'flex items-center gap-1.5 rounded-lg px-3 py-1.5 text-sm transition-colors',
            canSubmit
              ? 'bg-primary text-primary-foreground hover:bg-primary/90'
              : 'bg-muted text-muted-foreground cursor-not-allowed',
          )}
        >
          <Send className="h-3.5 w-3.5" />
          提交
        </button>
      </div>
    </div>
  )
}
